#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
patch_brat_metki.py — первый камень папки меток Брата.
Три этажа: 1_очень_важно / 2_важно / 3_не_очень_важно + README.
Запускать из корня репо Evgen-art-p/-2. Идемпотентен:
существующие файлы НЕ перезаписывает (бэкап .bak если отличается).
  шесть·проверено·до·корня
"""
import os, shutil, datetime

FILES = {
    'studio/Брат/метки/1_очень_важно/ЗЕРНО.md': '',
    'studio/Брат/метки/2_важно/ЗАКОНЫ.md': '',
    'studio/Брат/метки/3_не_очень_важно/МАЯЧКИ.md': '',
    'studio/Брат/метки/README.md': '',
}

import base64
def main():
    ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    created, skipped, backed = 0, 0, 0
    for path, b64 in FILES.items():
        content = base64.b64decode(b64).decode("utf-8")
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if os.path.exists(path):
            with open(path, encoding="utf-8") as f:
                cur = f.read()
            if cur == content:
                print(f"  = без изменений: {path}"); skipped += 1; continue
            shutil.copy2(path, f"{path}.bak_{ts}")
            print(f"  ~ бэкап + обновлён: {path}"); backed += 1
        else:
            print(f"  + создан: {path}"); created += 1
        with open(path, "w", encoding="utf-8") as f:
            f.write(content)
    print(f"\nГотово. создано={created} обновлено={backed} без_изм={skipped}")
    print("шесть·проверено·до·корня")

if __name__ == "__main__":
    main()
